.portfolio-wrap {
  max-width: 500px;
  margin: 0 auto;
  font-family: Inter, sans-serif;
}
.hero-section {
  padding-bottom: 16px;
  border-bottom: 1px solid #e2e8f0;
}
.hero-section h1 { margin: 0 0 4px 0; font-size: 22px; }
.hero-section p { margin: 0 0 8px 0; color: #64748b; font-size: 14px; }
.badge { background: #dcfce7; color: #166534; padding: 4px 10px; border-radius: 9999px; font-size: 11px; font-weight: 600; }
.project-grid { display: flex; flex-direction: column; gap: 10px; margin-top: 10px; }
.project-card { border: 1px solid #e2e8f0; border-radius: 8px; padding: 12px; }
.project-title { margin: 0 0 4px 0; font-size: 14px; }
.project-desc { margin: 0 0 8px 0; font-size: 12.5px; color: #475569; }
.project-tags { display: flex; gap: 4px; }
.tag-pill { background: #f1f5f9; padding: 2px 6px; border-radius: 4px; font-size: 11px; color: #475569; }

